"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
from collections import deque, defaultdict
import heapq

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Uses Dijkstra with a binary heap for O((V+E) log V) time for non-negative weights.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    # Quick path for trivial case
    if source == target:
        return 0.0, [source]

    # Dijkstra's algorithm
    dist: Dict[int, float] = {n: float('inf') for n in nodes}
    prev: Dict[int, Optional[int]] = {n: None for n in nodes}
    dist[source] = 0.0

    heap: List[Tuple[float, int]] = [(0.0, source)]

    while heap:
        d, u = heapq.heappop(heap)
        # stale entry
        if d > dist[u]:
            continue
        if u == target:
            break
        for v, w in graph.neighbors(u):
            newd = d + w
            if newd < dist[v]:
                dist[v] = newd
                prev[v] = u
                heapq.heappush(heap, (newd, v))

    if dist[target] == float('inf'):
        return None, []

    # Reconstruct path
    path: List[int] = []
    cur: Optional[int] = target
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Uses a single Dijkstra run to compute distances and predecessors.
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist: Dict[int, float] = {n: float('inf') for n in nodes}
    prev: Dict[int, Optional[int]] = {n: None for n in nodes}
    dist[source] = 0.0

    heap: List[Tuple[float, int]] = [(0.0, source)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in graph.neighbors(u):
            newd = d + w
            if newd < dist[v]:
                dist[v] = newd
                prev[v] = u
                heapq.heappush(heap, (newd, v))

    result: Dict[int, Tuple[float, List[int]]] = {}
    for n in nodes:
        if dist[n] != float('inf'):
            # Reconstruct path for n
            path: List[int] = []
            cur: Optional[int] = n
            while cur is not None:
                path.append(cur)
                cur = prev[cur]
            path.reverse()
            result[n] = (dist[n], path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Implements an early-termination Dijkstra: stops after k nearest nodes are settled.
    """
    if k <= 0:
        return []

    nodes = graph.nodes
    if source not in nodes:
        return []

    dist: Dict[int, float] = {n: float('inf') for n in nodes}
    dist[source] = 0.0
    heap: List[Tuple[float, int]] = [(0.0, source)]
    visited: Set[int] = set()
    result: List[Tuple[int, float]] = []

    while heap and len(result) < k:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u in visited:
            continue
        visited.add(u)
        if u != source:
            result.append((u, d))
            if len(result) >= k:
                break
        for v, w in graph.neighbors(u):
            newd = d + w
            if newd < dist[v]:
                dist[v] = newd
                heapq.heappush(heap, (newd, v))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Uses BFS (ignoring weights) for O(V + E) time.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True

    q = deque([source])
    visited: Set[int] = {source}

    while q:
        u = q.popleft()
        for v, _ in graph.neighbors(u):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                q.append(v)
    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Builds an undirected adjacency view and runs BFS/DFS to collect components in O(V + E).
    """
    nodes = graph.nodes
    # Build undirected adjacency
    undirected: Dict[int, Set[int]] = {n: set() for n in nodes}
    for u in nodes:
        for v, _ in graph.neighbors(u):
            undirected[u].add(v)
            # ensure reverse edge
            if v in undirected:
                undirected[v].add(u)
            else:
                undirected[v] = {u}

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for node in nodes:
        if node in visited:
            continue
        # BFS/DFS to gather component
        stack = [node]
        comp: Set[int] = set()
        visited.add(node)
        while stack:
            u = stack.pop()
            comp.add(u)
            for v in undirected.get(u, ()):
                if v not in visited:
                    visited.add(v)
                    stack.append(v)
        components.append(comp)

    return components
